# recovered from src/routes.js
openapi: 3.1.0
info: { title: "permit-intake API", version: "0.0.0" }
paths:
  /applications:
    post:
      operationId: submitApplication
      summary: Submit a permit application
      responses:
        "201": { description: the stored application }
        "400": { description: the applicant is under the age minimum }
  /applications/{id}:
    get:
      operationId: getApplication
      summary: Look a permit application up by its id
      parameters:
        - { name: id, in: path, required: true, schema: { type: string } }
      responses:
        "200": { description: the stored application }
        "404": { description: no application has that id }

